From a1df5fdc44fa8f70acac97ad8ec223520b5a2795 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 12:28:37 +0100
Subject: [PATCH] plugins/nightlight: suspend with the shortcut until manually
 resumed

The Suspend/Resume shortcut inhibited Night Light globally, which the
brightness applet can't lift, so its switch was greyed out until the
shortcut was used again. The shortcut now uses manual deactivation.

BUG: 487617
---
 src/plugins/nightlight/nightlightmanager.cpp | 51 ++++++++++++--------
 src/plugins/nightlight/nightlightmanager.h   |  4 +-
 2 files changed, 33 insertions(+), 22 deletions(-)

diff --git a/src/plugins/nightlight/nightlightmanager.cpp b/src/plugins/nightlight/nightlightmanager.cpp
index baa28220ef..65ece9130c 100644
--- a/src/plugins/nightlight/nightlightmanager.cpp
+++ b/src/plugins/nightlight/nightlightmanager.cpp
@@ -48,23 +48,7 @@ NightLightManager::NightLightManager()

     // Display a message when Night Light is (un)inhibited.
     connect(this, &NightLightManager::inhibitedChanged, this, [this] {
-        const QString iconName = isInhibited()
-            ? QStringLiteral("redshift-status-off")
-            : m_daylight && m_targetTemperature != DEFAULT_DAY_TEMPERATURE ? QStringLiteral("redshift-status-day")
-                                                                           : QStringLiteral("redshift-status-on");
-
-        const QString text = isInhibited()
-            ? i18nc("Night Light was temporarily disabled", "Night Light Suspended")
-            : i18nc("Night Light was reenabled from temporary suspension", "Night Light Resumed");
-
-        QDBusMessage message = QDBusMessage::createMethodCall(
-            QStringLiteral("org.kde.plasmashell"),
-            QStringLiteral("/org/kde/osdService"),
-            QStringLiteral("org.kde.osdService"),
-            QStringLiteral("showText"));
-        message.setArguments({iconName, text});
-
-        QDBusConnection::sessionBus().asyncCall(message);
+        showSuspendedOsd(isInhibited());
     });

     m_configWatcher = KConfigWatcher::create(kwinApp()->config());
@@ -122,8 +106,37 @@ void NightLightManager::reconfigure()

 void NightLightManager::toggle()
 {
-    m_isGloballyInhibited = !m_isGloballyInhibited;
-    m_isGloballyInhibited ? inhibit() : uninhibit();
+    const bool suspend = !isTemporarilyDeactivated(QDateTime::currentDateTime());
+
+    tryActivateOrDeactivate([this, suspend]() {
+        m_activatedUntilDateTime = QDateTime();
+        m_activatedManual = false;
+        m_deactivatedUntilDateTime = QDateTime();
+        m_deactivatedManual = suspend;
+    });
+
+    showSuspendedOsd(suspend);
+}
+
+void NightLightManager::showSuspendedOsd(bool suspended)
+{
+    const QString iconName = suspended
+        ? QStringLiteral("redshift-status-off")
+        : m_daylight && m_targetTemperature != DEFAULT_DAY_TEMPERATURE ? QStringLiteral("redshift-status-day")
+                                                                       : QStringLiteral("redshift-status-on");
+
+    const QString text = suspended
+        ? i18nc("Night Light was temporarily disabled", "Night Light Suspended")
+        : i18nc("Night Light was reenabled from temporary suspension", "Night Light Resumed");
+
+    QDBusMessage message = QDBusMessage::createMethodCall(
+        QStringLiteral("org.kde.plasmashell"),
+        QStringLiteral("/org/kde/osdService"),
+        QStringLiteral("org.kde.osdService"),
+        QStringLiteral("showText"));
+    message.setArguments({iconName, text});
+
+    QDBusConnection::sessionBus().asyncCall(message);
 }

 bool NightLightManager::isInhibited() const
diff --git a/src/plugins/nightlight/nightlightmanager.h b/src/plugins/nightlight/nightlightmanager.h
index 33e139b4f9..c6d66db934 100644
--- a/src/plugins/nightlight/nightlightmanager.h
+++ b/src/plugins/nightlight/nightlightmanager.h
@@ -312,6 +312,7 @@ private:
     void setDaylight(bool daylight);

     void tryActivateOrDeactivate(std::function<void()> callback);
+    void showSuspendedOsd(bool suspended);

     NightLightDBusInterface *m_iface;
     KSystemClockSkewNotifier *m_skewNotifier;
@@ -331,9 +332,6 @@ private:
     // Specifies whether Night Light is currently running.
     bool m_running = false;

-    // Specifies whether Night Light is inhibited globally.
-    bool m_isGloballyInhibited = false;
-
     NightLightMode m_mode = NightLightMode::DarkLight;

     // the previous and next sunrise/sunset intervals - in UTC time
